node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search for the product
let rows = db.prepare(\"SELECT * FROM products WHERE name LIKE '%VoltForge%' OR name LIKE '%Wireless Charging%' OR name LIKE '%Charging Stand%'\").all();
console.log('=== Products matching name ===');
console.log(JSON.stringify(rows, null, 2));

// Search by product_id pattern
rows = db.prepare(\"SELECT * FROM products WHERE product_id LIKE '%2028%'\").all();
console.log('=== Products matching ID 2028 ===');
console.log(JSON.stringify(rows, null, 2));

// List all column names in products table
const info = db.prepare(\"PRAGMA table_info(products)\").all();
console.log('=== Products columns ===');
console.log(info.map(c => c.name));
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check rt_variants for this product
let rows = db.prepare(\"SELECT * FROM rt_variants WHERE product_id='PROD-2028EE'\").all();
console.log('=== Variants ===');
console.log(JSON.stringify(rows, null, 2));

// Check specs and compatible_with in detail
let product = db.prepare(\"SELECT specs_json, compatible_with_json, description FROM products WHERE product_id='PROD-2028EE'\").get();
console.log('=== Specs ===', product.specs_json);
console.log('=== Compatible With ===', product.compatible_with_json);
console.log('=== Description ===', product.description);
"
